import json
n=19
g=[[0]*n for _ in range(n)]
# Colored centers and their 3-valued cross arms, using zero-based (row, col).
centers={(3,6):8,(4,13):4,(12,14):1,(14,3):2}
for (r,c),color in centers.items():
    g[r][c]=color
    for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
        g[rr][cc]=3
# An additional uncolored cross.
for r,c in ((9,8),(11,8),(10,7),(10,9)):
    g[r][c]=3
out=[row[:] for row in g]
# Extend each colored center across its full row and column. Preserve original 3 markers;
# at intersections of an extended row and column, the vertical line takes precedence.
for (r,c),color in centers.items():
    for j in range(n):
        if g[r][j] != 3:
            out[r][j]=color
for (r,c),color in centers.items():
    for i in range(n):
        if g[i][c] != 3:
            out[i][c]=color
assert len(out)==19 and all(len(row)==19 for row in out)
assert all(0<=v<=9 for row in out for v in row)
print(json.dumps(out,separators=(',',':')))

